"use client";
import { RiAddLine } from "@remixicon/react";
import { useState } from "react";
import { Dialog, Heading, Modal, ModalOverlay } from "react-aria-components";
import { Button } from "../../base/buttons/button";
import { Input } from "../../base/input/input";
import { ContributionsCard } from "../charts/contributions-card";
import { EarningsChartCard } from "../charts/earnings-chart-card";
import { LineChartCard } from "../charts/line-chart-card";
import { StatCards } from "../dashboard/stat-cards";
import {
  createCustomerRows,
  DataTableExample,
  type CustomerRecord,
} from "../data-table/data-table";
import { RecentHiresCard, type RecentHire } from "./recent-hires-card";
import { TemplateShell, type TemplateShellProps } from "./template-shell";

const HOME_CUSTOMERS = createCustomerRows(660);

export interface HomeDashboardProps
  extends Pick<TemplateShellProps, "account" | "accounts" | "team" | "navigationItems"> {
  contained?: boolean;
  className?: string;
  onCreateTicket?: (title: string) => void;
  enableTicketCreation?: boolean;
  heading?: string;
  hires?: RecentHire[];
  rows?: CustomerRecord[];
}
export function HomeDashboard({
  contained,
  className,
  onCreateTicket,
  enableTicketCreation,
  heading,
  hires,
  rows = HOME_CUSTOMERS,
  account,
  accounts,
  team,
  navigationItems,
}: HomeDashboardProps = {}) {
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [created, setCreated] = useState("");
  return (
    <TemplateShell
      title="Home"
      heading={heading ?? `Welcome ${account?.name.split(" ")[0] ?? "Jordan"}`}
      account={account}
      accounts={accounts}
      team={team}
      navigationItems={navigationItems}
      selected="home"
      contained={contained}
      className={className}
      onAction={onCreateTicket || enableTicketCreation ? () => setOpen(true) : undefined}
    >
      <div className="flex w-full flex-col gap-4">
        <div className="flex w-full flex-col items-stretch gap-4 xl:flex-row xl:items-start">
          <RecentHiresCard hires={hires} team={team?.name} />
          <EarningsChartCard />
        </div>
        <div className="flex w-full flex-col items-stretch gap-4 lg:flex-row lg:items-start">
          <LineChartCard className="h-[337px]! flex-1 gap-6" />
          <ContributionsCard />
        </div>
        <StatCards />
        <DataTableExample rows={rows} layout="fluid" pageSize={12} showSizeToggle={false} />
      </div>
      {created && (
        <p
          role="status"
          className="rounded-xl bg-status-lime-background px-4 py-3 text-body-medium text-status-lime-text"
        >
          Ticket created: {created}
        </p>
      )}
      <ModalOverlay
        isOpen={open}
        onOpenChange={setOpen}
        isDismissable
        className="fixed inset-0 z-50 flex items-center justify-center bg-background-modal-overlay p-4 backdrop-blur-sm"
      >
        <Modal className="w-full max-w-md rounded-3xl border border-border-button-default bg-background-primary-default p-6 shadow-dropdown">
          <Dialog className="outline-none">
            <form
              onSubmit={(event) => {
                event.preventDefault();
                if (!title.trim()) return;
                onCreateTicket?.(title.trim());
                setCreated(title.trim());
                setTitle("");
                setOpen(false);
              }}
              className="flex flex-col gap-4"
            >
              <Heading slot="title" className="text-title-3-medium text-text-primary">
                Create ticket
              </Heading>
              <Input label="Ticket title" value={title} onChange={setTitle} isRequired autoFocus />
              <div className="flex justify-end gap-2">
                <Button variant="secondary" onClick={() => setOpen(false)}>
                  Cancel
                </Button>
                <Button type="submit" leadingIcon={RiAddLine}>
                  Create ticket
                </Button>
              </div>
            </form>
          </Dialog>
        </Modal>
      </ModalOverlay>
    </TemplateShell>
  );
}
